import pyomo.environ as pyo

DATA = {
    "departments": ["X", "Y", "Z"],
    "total_limit": 1000,
    "x_minus_y": 200,
    "y_minus_z": 100,
    "cost": {"X": 50, "Y": 60, "Z": 70},
    "capacity": {"X": 500, "Y": 400, "Z": 300},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.D = pyo.Set(initialize=d["departments"], ordered=True)

    def staff_bounds(m, i):
        return (0, d["capacity"][i])

    model.staff = pyo.Var(
        model.D,
        within=pyo.NonNegativeIntegers,
        bounds=staff_bounds,
    )

    def obj_rule(m):
        return sum(d["cost"][i] * m.staff[i] for i in m.D)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_limit_rule(m):
        return sum(m.staff[i] for i in m.D) <= d["total_limit"]

    model.total_limit = pyo.Constraint(rule=total_limit_rule)

    def x_minus_y_rule(m):
        return m.staff["X"] - m.staff["Y"] >= d["x_minus_y"]

    model.x_minus_y = pyo.Constraint(rule=x_minus_y_rule)

    def y_minus_z_rule(m):
        return m.staff["Y"] - m.staff["Z"] >= d["y_minus_z"]

    model.y_minus_z = pyo.Constraint(rule=y_minus_z_rule)

    return model


