import pyomo.environ as pyo

DATA = {
    "DEPTS": ["X", "Y", "Z"],
    "COST": {"X": 50, "Y": 60, "Z": 70},
    "MAX_TOTAL_WORKERS": 1000,
    "GAP_X_OVER_Y": 200,
    "GAP_Y_OVER_Z": 100,
    "UB": {"X": 500, "Y": 400, "Z": 300},
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.DEPT = pyo.Set(initialize=d["DEPTS"], ordered=True)

    def ub_rule(m, dep):
        return (0, d["UB"][dep])

    model.x = pyo.Var(
        model.DEPT,
        domain=pyo.NonNegativeIntegers,
        bounds=ub_rule,
    )

    def total_workers_rule(m):
        return sum(m.x[dep] for dep in m.DEPT) <= d["MAX_TOTAL_WORKERS"]

    model.total_workers_cap = pyo.Constraint(rule=total_workers_rule)

    def gap_x_over_y_rule(m):
        return m.x["X"] - m.x["Y"] >= d["GAP_X_OVER_Y"]

    model.gap_x_over_y = pyo.Constraint(rule=gap_x_over_y_rule)

    def gap_y_over_z_rule(m):
        return m.x["Y"] - m.x["Z"] >= d["GAP_Y_OVER_Z"]

    model.gap_y_over_z = pyo.Constraint(rule=gap_y_over_z_rule)

    def capacity_rule(m, dep):
        return m.x[dep] <= d["UB"][dep]

    model.capacity = pyo.Constraint(model.DEPT, rule=capacity_rule)

    def obj_rule(m):
        return sum(d["COST"][dep] * m.x[dep] for dep in m.DEPT)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    return model
